import json
import os
import argparse
from typing import Dict, List, Any

def parse_endpoints_info(data: List[Dict[str, Any]]) -> Dict[str, Any]:
    endpoint_info = dict()
    for (k,v) in data.items():
        for handler in v:
            if "/".join(handler.get("path'")) != "":
                if endpoint_info.get(k) == None:
                    endpoint_info[k] = []
                endpoint_info[k].append("/".join(handler.get("path'")))

    return endpoint_info


def process_files(directory: str) -> List[Dict[str, Any]]:
    all_endpoints_info = []
    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith(".module_apis.json"):
                file_path = os.path.join(root, file)
                with open(file_path, "r") as f:
                    data = json.load(f)
                    d = parse_endpoints_info(data)
                    if len(d) != 0:
                        all_endpoints_info.append(d)
    return all_endpoints_info


def write_output(data: List[Dict[str, Any]], output_path: str):
    # Ensure the directory exists
    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    with open(output_path, 'w') as f:
        json.dump(data, f, indent=2)


def main():
    parser = argparse.ArgumentParser(description='Process environment information and write to specified output path')
    parser.add_argument('--input-dir', default='./tmp', help='Input directory containing typeUpdates.json files')
    parser.add_argument('--output-path', required=True, help='Path where the output JSON file should be written')

    args = parser.parse_args()

    endpoints_info = process_files(args.input_dir)
    if len(endpoints_info) != 0:
        write_output(endpoints_info, args.output_path)
        print(f"Output written to: {args.output_path}")


if __name__ == "__main__":
    main()

import os
import json
import re
import argparse
from typing import Any, Dict, List

def extract_details(obj):
    instance_type = obj.get("instanceType", "")
    print(f"Instance Type: {instance_type}")
    if "typeerror" in instance_type.lower():
        return None

    enum_match = re.search(r"ServiceConfigKey\s+(\w+)", instance_type)
    enum = enum_match.group(1) if enum_match else None
    print(f"Enum: {enum}")

    instance_definition = obj.get("instanceDefinition", "").replace('\\n', ' ').replace('\\', '')
    match = re.search(r'getKey\s*\(?[^\)]+?\)?\s*=\s*(.*)', instance_definition)

    if match:
        after_equal = match.group(1).strip()
        parts = re.findall(r'[_A-Za-z0-9]+', after_equal)

        if parts:
            basekey = max(parts, key=len)
            dimensions = [part for part in parts if part != basekey]
        else:
            basekey = None
            dimensions = []
    else:
        basekey = None
        dimensions = []

    if enum and basekey:
        return {
            "enum": enum,
            "basekey": basekey,
            "dimensions": dimensions if dimensions else None
        }
    return None

def process_json_file(file_path):
    extracted_keys = []

    with open(file_path, 'r') as file:
        data = json.load(file)

    if isinstance(data, list):
        for obj in data:
            if "instanceType" in obj and "ServiceConfigKey" in obj.get("instanceType", ""):
                details = extract_details(obj)
                if details:
                    extracted_keys.append(details)
    elif isinstance(data, dict):
        if "instanceType" in data and "ServiceConfigKey" in data.get("instanceType", ""):
            details = extract_details(data)
            if details:
                extracted_keys.append(details)

    return extracted_keys

def search_and_extract(folder):
    all_keys = []

    for root, _, files in os.walk(folder):
        for file in files:
            if file.endswith('instance_code.json'):
                file_path = os.path.join(root, file)
                keys = process_json_file(file_path)
                all_keys.extend(keys)

    return all_keys

def write_output(data: List[Dict[str, Any]], output_path: str):
    # Ensure the directory exists
    os.makedirs(os.path.dirname(output_path), exist_ok=True)

    with open(output_path, 'w') as f:
        json.dump(data, f, indent=2)
